public class PunctuationStripper {

    public static String stripPunctuation(String s) {
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (Character.isLetterOrDigit(c) || c == ' ') {
                result.append(c);
            }
        }
        return result.toString();
    }
}
